//! TypeScript bindings for the studio, generated from the Rust wire types (ts-rs).
//!
//! `render` joins every declaration into one file, `studio/src/generated/types.ts`, so the
//! studio imports one module and no per-type import paths. A test fails when the committed file
//! drifts; `just types` rewrites it.

use ts_rs::{Config, TS};

/// Where the generated file lives, relative to the workspace root.
pub const TS_PATH: &str = "studio/src/generated/types.ts";

const HEADER: &str =
    "// Generated by `just types` from the Rust types (ck-server ts_types). Do not edit.\n";

/// The whole bindings file. Integers are JSON numbers (every value stays under 2^53).
pub fn render() -> String {
    let cfg = Config::new().with_large_int("number");
    let mut out = String::from(HEADER);
    for decl in decls(&cfg) {
        out.push_str("\nexport ");
        out.push_str(&decl);
        out.push('\n');
    }
    out
}

/// Every type the studio reads or sends, in a stable order. A type missing here that another
/// one references leaves a dangling name, which the completeness test catches.
fn decls(cfg: &Config) -> Vec<String> {
    use crate::event::Event;
    use crate::session::{HeartbeatRequest, LockRequest, LockResult, PatchResult, UnlockRequest};
    use crate::view::{ItemSummary, Status, Summary, TrackSummary};
    use ck_core::model::*;
    use ck_core::patch::PatchRequest;
    use ck_core::{CkError, ErrorCode};
    vec![
        // Project model (spec 3.2).
        Project::decl(cfg),
        Mode::decl(cfg),
        Settings::decl(cfg),
        Track::decl(cfg),
        TrackKind::decl(cfg),
        Item::decl(cfg),
        ItemBody::decl(cfg),
        CaptionFrom::decl(cfg),
        TimeRange::decl(cfg),
        Source::decl(cfg),
        SourceKind::decl(cfg),
        VoiceSlot::decl(cfg),
        VoiceMode::decl(cfg),
        VoiceSlotStatus::decl(cfg),
        VoiceTake::decl(cfg),
        Comment::decl(cfg),
        CommentStatus::decl(cfg),
        Anchor::decl(cfg),
        Point::decl(cfg),
        Reply::decl(cfg),
        Author::decl(cfg),
        Brief::decl(cfg),
        BriefField::decl(cfg),
        BriefQuestion::decl(cfg),
        BriefSource::decl(cfg),
        BriefStatus::decl(cfg),
        Lock::decl(cfg),
        Holder::decl(cfg),
        PipelineState::decl(cfg),
        Stage::decl(cfg),
        Pass::decl(cfg),
        AgentState::decl(cfg),
        AgentStatus::decl(cfg),
        // API requests, replies and errors (spec 6.2).
        PatchRequest::decl(cfg),
        PatchResult::decl(cfg),
        LockRequest::decl(cfg),
        UnlockRequest::decl(cfg),
        HeartbeatRequest::decl(cfg),
        LockResult::decl(cfg),
        Status::decl(cfg),
        Summary::decl(cfg),
        TrackSummary::decl(cfg),
        ItemSummary::decl(cfg),
        CkError::decl(cfg),
        ErrorCode::decl(cfg),
        // WebSocket push.
        Event::decl(cfg),
        // Untyped JSON (plan, tokens, props; typed in later phases).
        serde_json::Value::decl(cfg),
    ]
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;
    use std::path::PathBuf;

    use super::*;

    fn committed_path() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .join(TS_PATH)
    }

    /// Fails when the Rust types and the committed bindings differ. `just types` regenerates.
    #[test]
    fn generated_types_match_committed_file() {
        let fresh = render();
        let path = committed_path();
        if std::env::var_os("CK_WRITE_TYPES").is_some() {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, &fresh).unwrap();
        }
        let committed = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            committed == fresh,
            "{TS_PATH} is stale or missing; run `just types` and commit the result"
        );
    }

    /// Every capitalised name used in a type position is declared in the file.
    #[test]
    fn every_referenced_type_is_declared() {
        let out = render();
        let declared: BTreeSet<&str> = out
            .lines()
            .filter_map(|l| l.strip_prefix("export type "))
            .filter_map(|l| l.split([' ', '<']).next())
            .collect();
        let builtin = ["Array", "Record", "Partial"];
        let mut missing = BTreeSet::new();
        for line in out.lines().filter(|l| !is_comment(l)) {
            let code = strip_strings_and_comments(line);
            for word in code.split(|c: char| !(c.is_ascii_alphanumeric() || c == '_')) {
                let upper = word.chars().next().is_some_and(|c| c.is_ascii_uppercase());
                if upper && !declared.contains(word) && !builtin.contains(&word) {
                    missing.insert(word.to_owned());
                }
            }
        }
        assert!(missing.is_empty(), "undeclared types: {missing:?}");
    }

    /// Integers travel as JSON numbers, never bigint.
    #[test]
    fn no_bigint_in_bindings() {
        assert!(!render().contains("bigint"));
    }

    fn is_comment(line: &str) -> bool {
        let t = line.trim_start();
        t.starts_with("//") || t.starts_with("/*") || t.starts_with('*')
    }

    fn strip_strings_and_comments(line: &str) -> String {
        let line = line.split("/*").next().unwrap_or_default();
        let mut out = String::new();
        let mut in_str = false;
        for c in line.chars() {
            if c == '"' {
                in_str = !in_str;
            } else if !in_str {
                out.push(c);
            }
        }
        out
    }
}
